SOURCE_ID = '3cc1e9b0-9b0c-435f-9ea3-c636f0002def'
SOURCE_HASH = 'a460e7e17f7a8fb50e73ccdfa76e79c534741fa7a854ff19585b955c5a60663a'
DESCRIPTION_KN = 'ಬ್ರದರ್ಸ್ ವರ್ಕ್\u200cಫೋರ್ಸ್ ಸೊಲ್ಯೂಷನ್ಸ್ ಮೈಸೂರು ಮತ್ತು ಮಂಗಳೂರಿನಲ್ಲಿ ಪೂರ್ಣಕಾಲಿಕ ಗ್ರಾಹಕ ಸೇವಾ ಕೆಲಸಗಳಿಗೆ ಪ್ರತಿನಿಧಿಗಳನ್ನು ನೇಮಿಸುತ್ತಿದೆ.\n\nಜವಾಬ್ದಾರಿಗಳು:\n• ಕಾರ್ಡ್ ಸದಸ್ಯರ ಒಳಬರುವ ಕರೆಗಳನ್ನು ಸ್ವೀಕರಿಸಿ, ಖಾತೆಯ ಬಾಕಿ, ಆರ್ಡರ್ ಸ್ಥಿತಿ ಮತ್ತು ಪಾವತಿ ನಿರಾಕರಣೆಯ ಪ್ರಶ್ನೆಗಳಿಗೆ ಸಹಾಯ ಮಾಡುವುದು.\n• ಪ್ರಕ್ರಿಯೆಯ ಮಾರ್ಗಸೂಚಿಗಳಂತೆ ಗ್ರಾಹಕರ ದೂರುಗಳನ್ನು ನಿಖರವಾಗಿ, ವೃತ್ತಿಪರವಾಗಿ ಮತ್ತು ಸಹಾನುಭೂತಿಯಿಂದ ದಾಖಲಿಸುವುದು.\n• ಗಮನವಿಟ್ಟು ಕೇಳಿ, ಗ್ರಾಹಕರ ಮಾತಿನ ಶೈಲಿ, ಸಾಂಸ್ಕೃತಿಕ ಹಿನ್ನೆಲೆ ಮತ್ತು ಭಾವನಾತ್ಮಕ ಸ್ಥಿತಿಗೆ ತಕ್ಕಂತೆ ಸಂವಹನ ಮಾಡುವುದು.\n• ಸಂಕೀರ್ಣ ಸಮಸ್ಯೆಗಳನ್ನು ಪರಿಣಾಮಕಾರಿಯಾಗಿ ಪರಿಹರಿಸಿ ಕರೆಗಳನ್ನು ಸಮರ್ಪಕವಾಗಿ ನಿರ್ವಹಿಸುವುದು.\n• ಕರೆಗಳ ಸಮಯದಲ್ಲಿ ಹಲವು ವ್ಯವಸ್ಥೆಗಳು ಮತ್ತು ಪರದೆಗಳನ್ನು ಬಳಸಿ ನಿಖರವಾಗಿ ಮಾಹಿತಿ ನಮೂದಿಸುವುದು.\n• ಕಂಪನಿಯ ಮಾರ್ಗಸೂಚಿಗಳು ಮತ್ತು ಅನುಸರಣೆ ನಿಯಮಗಳಂತೆ ಪ್ರಕರಣಗಳನ್ನು ದಾಖಲಿಸಿ ಕ್ರಮ ಕೈಗೊಳ್ಳುವುದು.\n• ನಿಗದಿತ ತರಬೇತಿ ಪೂರ್ಣಗೊಳಿಸಿ ಪ್ರಕ್ರಿಯೆ ಅಥವಾ ನೀತಿ ಬದಲಾವಣೆಗಳಿಗೆ ಬೇಗ ಹೊಂದಿಕೊಳ್ಳುವುದು.\n\nವಿದ್ಯಾರ್ಹತೆ ಮತ್ತು ಕೌಶಲ್ಯಗಳು:\n• ಸಂಬಂಧಿತ ಕ್ಷೇತ್ರದಲ್ಲಿ ಪದವಿ ಅಥವಾ ಡಿಪ್ಲೊಮಾ, ಅಥವಾ ಸಮಾನ ಅನುಭವ.\n• ಇಂಗ್ಲಿಷ್\u200cನಲ್ಲಿ ಚೆನ್ನಾಗಿ ಬರೆಯುವ ಮತ್ತು ಮಾತನಾಡುವ ಸಾಮರ್ಥ್ಯ.\n• ಉತ್ತಮ ಗ್ರಾಹಕ ಸೇವೆ, ಗಮನವಿಟ್ಟು ಕೇಳುವಿಕೆ, ಸಂವಹನ ಮತ್ತು ಸಮಸ್ಯೆ ಪರಿಹಾರ ಕೌಶಲ್ಯಗಳು.\n• ಕಂಪ್ಯೂಟರ್, ಬ್ರೌಸರ್ ಮತ್ತು ಇಂಟರ್ನೆಟ್ ಬಳಕೆಯ ಕೌಶಲ್ಯಗಳು.\n• ನಿಖರ ಟಚ್ ಟೈಪಿಂಗ್ ಮತ್ತು ಏಕಕಾಲದಲ್ಲಿ ಹಲವು ಕೆಲಸಗಳನ್ನು ಮಾಡುವ ಸಾಮರ್ಥ್ಯ.\n• ವಿವಿಧ ಸಾಂಸ್ಕೃತಿಕ ಹಿನ್ನೆಲೆಯ ಗ್ರಾಹಕರಿಗೆ ಸಹಾಯ ಮಾಡಿದ ಅನುಭವ.\n• ಬಹುಭಾಷಾ ಸಂಪರ್ಕ ಕೇಂದ್ರ ಅಥವಾ ಗ್ರಾಹಕ ಸೇವೆಯ ಹಿಂದಿನ ಅನುಭವಕ್ಕೆ ಆದ್ಯತೆ.\n• ಹಣಕಾಸು ಸೇವೆಗಳು, ಪಾವತಿ ವ್ಯವಸ್ಥೆಗಳು ಅಥವಾ ಕಾರ್ಡ್ ಸದಸ್ಯರ ಸೇವೆಯ ಅನುಭವ ಅನುಕೂಲಕರ.\n• ಸೂಕ್ಷ್ಮ ಮಾಹಿತಿಯನ್ನು ನಿರ್ವಹಿಸುವ ಮತ್ತು ಹಿನ್ನೆಲೆ ಪರಿಶೀಲನೆಯ ಅಗತ್ಯಗಳನ್ನು ಪೂರೈಸುವ ಸಾಮರ್ಥ್ಯ.\n\nಉದ್ಯೋಗದ ವಿಧ: ಪೂರ್ಣಕಾಲಿಕ\nಸ್ಥಳ: ಮೈಸೂರು / ಮಂಗಳೂರು\nಪಾಳಿ: ರಾತ್ರಿ ಪಾಳಿಯೂ ಸೇರಿದಂತೆ ಬದಲಾಗುವ ಪಾಳಿಗಳು\n\nಅಭ್ಯರ್ಥಿಗಳಿಂದ ಯಾವುದೇ ಸೇವಾ ಅಥವಾ ಅರ್ಜಿ ಶುಲ್ಕವನ್ನು ಪಡೆಯುವುದಿಲ್ಲ.'

async def translate_known_job(db):
    job = await db.jobs.find_one({"id": SOURCE_ID})
    if not job or hashlib.sha256((job.get("description") or "").encode()).hexdigest() != SOURCE_HASH:
        return
    changes = {}
    for key, value in {"description_kn": DESCRIPTION_KN, "title_kn": "ಒಳಬರುವ ಕರೆಗಳ ಗ್ರಾಹಕ ಸೇವಾ ಪ್ರತಿನಿಧಿ", "location_kn": "ಮೈಸೂರು / ಮಂಗಳೂರು", "experience_kn": "ಗ್ರಾಹಕ ಸೇವೆಯ ಅನುಭವಕ್ಕೆ ಆದ್ಯತೆ", "shift_kn": "ರಾತ್ರಿ ಪಾಳಿಯೂ ಸೇರಿದಂತೆ ಬದಲಾಗುವ ಪಾಳಿಗಳು", "qualification": "Relevant bachelor's degree or diploma, or equivalent experience", "qualification_kn": "ಸಂಬಂಧಿತ ಕ್ಷೇತ್ರದಲ್ಲಿ ಪದವಿ ಅಥವಾ ಡಿಪ್ಲೊಮಾ, ಅಥವಾ ಸಮಾನ ಅನುಭವ"}.items():
        if not job.get(key):
            changes[key] = value
    if changes:
        changes["updated_at"] = datetime.now(timezone.utc)
        await db.jobs.update_one({"id": SOURCE_ID, "description": job["description"]}, {"$set": changes})
